const raw = $input.first().json;
const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
const msg = data.choices[0].message;
const content = (typeof msg.content === 'string' && msg.content.trim())
  ? msg.content
  : (typeof msg.reasoning_content === 'string' ? msg.reasoning_content : '');
const outline = JSON.parse(content.replace(/```json/g, '').replace(/```/g, '').trim());
const norm = (ch, i) => {
  if (ch && typeof ch === 'object') {
    const t = String(ch.title || ch.chapter_title || ('第' + (i + 1) + '章 开局'));
    return { title: t, outline: String(ch.outline || ch.content || ch.summary || JSON.stringify(ch)), hook: String(ch.hook || ''), hook_type: String(ch.hook_type || ''), emotion: String(ch.emotion || ''), pacing: String(ch.pacing || ''), scenes: Array.isArray(ch.scenes) ? ch.scenes : [] };
  }
  const s = String(ch || ('第' + (i + 1) + '章 开局'));
  return { title: s, outline: s, hook: '' };
};
const arr = Array.isArray(outline.chapter_outlines) && outline.chapter_outlines.length >= 2
  ? outline.chapter_outlines.map(norm)
  : [{ title: '第1章 开局', outline: '主角获得金手指并定下目标', hook: '' }, { title: '第2章 转折', outline: '遭遇第一次危机并化解', hook: '' }];
return [{ json: { premise: outline.premise || $json.premise, genre: outline.genre || '', title: outline.title || '', keywords: (outline.keywords || []).join(','), chapter1: arr[0], chapter2: arr[1] } }];

const ref = $('审稿A').first().json;
const data = typeof ref === 'string' ? JSON.parse(ref) : ref;
const msg = data.choices[0].message;
const reviewText = (typeof msg.content === 'string' && msg.content.trim())
  ? msg.content
  : (typeof msg.reasoning_content === 'string' ? msg.reasoning_content : '');
const extract = (s) => {
  const t = String(s).replace(/```json/g, '').replace(/```/g, '').trim();
  try { return JSON.parse(t); } catch {
    const m = t.match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
    throw new Error('审稿JSON解析失败: ' + t.slice(0, 200));
  }
};
const review = extract(reviewText);
const editedRef = $('润色A').first().json;
const editedData = typeof editedRef === 'string' ? JSON.parse(editedRef) : editedRef;
const emsg = editedData.choices[0].message;
const editedText = (typeof emsg.content === 'string' && emsg.content.trim())
  ? emsg.content
  : (typeof emsg.reasoning_content === 'string' ? emsg.reasoning_content : '');
if (!editedText) { throw new Error('润色A正文为空'); }
const chars = (editedText.match(/[\u4e00-\u9fff]/g) || []).length;
if (!review.passed || chars < 1500) { throw new Error('章节A未过质量门 chars=' + chars + ' review=' + JSON.stringify(review)); }
return [{ json: { review, chars, editedText, title: $('解析大纲').item.json.chapter1 } }];

const item = $input.first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let paras = item.editedText.split(/\n+/).map(s => s.trim()).filter(Boolean);
if (paras.length <= 1) {
  const t = (paras[0] || '').trim();
  paras = [];
  let buf = '';
  for (const ch of t) {
    buf += ch;
    if (buf.length >= 80 && '。！？；'.includes(ch)) {
      paras.push(buf.trim());
      buf = '';
    }
  }
  if (buf.trim()) paras.push(buf.trim());
}
const contentHtml = paras.map(p => '<p>' + esc(p) + '</p>').join('');
const cfg = $('设定题材').first().json;
return [{ json: { content_html: contentHtml, title: item.title, book_id: String(cfg.book_id || '') } }];

