const raw = $input.first().json;
const resp = typeof raw === 'string' ? JSON.parse(raw) : raw;
const data = resp && typeof resp.data === 'object' && resp.data !== null ? resp.data : resp;
const src = $('排版A').first().json;
const ch = src.title;
const rawTitle = typeof ch === 'string' ? ch : (ch && typeof ch === 'object' ? (ch.title || ch.chapter_title || '') : '');
const cleanTitle = String(rawTitle).replace(/^\s*第\s*\d+\s*章[：:\s]*/, '');
const startNum = Number($('算章节号').first().json.start_num || 1);
const n = startNum + 0;
const title = '第 ' + n + ' 章 ' + cleanTitle;
let volumeId = String(data.volume_id ?? '');
let volumeName = '正文';
let vd = data.volume_data;
if (typeof vd === 'string') { try { vd = JSON.parse(vd); } catch { vd = null; } }
if (Array.isArray(vd)) {
  const hit = vd.find(v => String(v.volume_id) === volumeId) || vd[0];
  if (hit && hit.volume_name) volumeName = hit.volume_name;
}
if (!data.item_id) { throw new Error('新建草稿未返回 item_id: ' + JSON.stringify(resp).slice(0, 300)); }
return [{ json: {
  item_id: String(data.item_id),
  book_id: src.book_id,
  volume_id: volumeId,
  volume_name: volumeName,
  title: title,
  content_html: src.content_html
} }];

