const raw = $input.first().json;
const bodyText = typeof raw.body === 'string' ? raw.body : JSON.stringify(raw);
let parsed = null;
try { parsed = JSON.parse(bodyText); } catch {}
if (!parsed || parsed.code !== 0) {
  throw new Error('番茄发布失败：' + ((parsed && parsed.message) || bodyText.slice(0, 300)));
}
return [{ json: { published: true, item_id: parsed.data && (parsed.data.item_id || parsed.data.article_id) || null, message: parsed.message } }];

