const input = $input.first().json;
const resp = typeof input.body === 'string' ? JSON.parse(input.body) : (input.body || input);
const list = resp && resp.data && Array.isArray(resp.data.book_list) ? resp.data.book_list : [];
const cfg = $('设定题材').first().json;
const target = list.find(b => String(b.book_id) === String(cfg.book_id)) || list[0] || {};
const startNum = (Number(target.chapter_number) || 0) + 1;
const bookName = String(target.book_name || '');
const abstract = String(target.abstract || '');
const metaNeeded = bookName.indexOf('用户') === 0 || abstract.length < 50;
return [{ json: { premise: cfg.premise, platform: cfg.platform, daily: cfg.daily, keywords: cfg.keywords, book_id: cfg.book_id, start_num: startNum, book_name: bookName, abstract: abstract, meta_needed: metaNeeded } }];

const raw = $input.first().json;
let prev = null;
try { prev = JSON.parse(raw.stdout || '{}'); } catch { prev = null; }
if (!prev || typeof prev !== 'object' || !prev.book_name) prev = null;
const src = $('算章节号').first().json;
return [{ json: { ...src, prev_meta: prev } }];

const raw = $input.first().json;
const resp = typeof raw === 'string' ? JSON.parse(raw) : raw;
const msg = resp.choices[0].message;
const content = (typeof msg.content === 'string' && msg.content.trim())
  ? msg.content
  : (typeof msg.reasoning_content === 'string' ? msg.reasoning_content : '');
const meta = JSON.parse(content.replace(/```json/g, '').replace(/```/g, '').trim());
const src = $('算章节号').first().json;
const prev = src.prev_meta || {};
const genre = String(meta.genre || src.genre || '');
let categoryId = '259';
let labels = ['259', '257'];
const g = genre;
if (/都市|赘婿|神医|战神/.test(g)) { categoryId = '124'; labels = ['124', '262']; }
else if (/玄幻/.test(g)) { categoryId = '258'; labels = ['258', '257']; }
else if (/科幻|末世/.test(g)) { categoryId = '8'; labels = ['8', '57']; }
else if (/悬疑|灵异|盗墓/.test(g)) { categoryId = '10'; labels = ['10', '539']; }
else if (/历史/.test(g)) { categoryId = '273'; labels = ['273', '272']; }
const oldProt = prev.protagonists && prev.protagonists[0];
const prot = meta.protagonist || {};
const protName = String(prot.name || (oldProt && oldProt.name) || '主角');
const protagonists = [{ name: protName, role: '主角', traits: String(prot.traits || (oldProt && oldProt.traits) || ''), goals: String(prot.goals || (oldProt && oldProt.goals) || '') }];
const secondary = String(meta.secondary_name || '');
if (secondary) protagonists.push({ name: secondary, role: '配角', traits: '', goals: '' });
const abstract = String(meta.abstract || src.abstract || '').replace(/\s+/g, ' ');
const bookName = String(meta.book_name || src.book_name || '未命名');
const tags = Array.isArray(meta.tags) && meta.tags.length ? meta.tags.map(String) : [];
const gender = (meta.gender === 0 || meta.gender === '0') ? '0' : '1';
return [{ json: {
  premise: src.premise, platform: src.platform, daily: src.daily, keywords: src.keywords,
  book_id: src.book_id, start_num: src.start_num,
  book_name: bookName, abstract: abstract, tags: tags, gender: gender,
  category_id: categoryId, label_id_list: labels.join(','),
  protagonists: protagonists, protagonist: protName, secondary_name: secondary,
  volume_goal: String(meta.volume_goal || ''), prev_meta: prev,
  meta_needed: src.meta_needed
} }];

const meta = $('解析作品资料').first().json;
const raw = $input.first().json;
const body = raw && typeof raw.body === 'string' ? JSON.parse(raw.body) : (raw && raw.body) || null;
const modifyResult = body && body.code === 0 ? 'ok' : JSON.stringify(body || raw).slice(0, 300);
return [{ json: { ...meta, modify_result: modifyResult } }];

const meta = $('解析作品资料').first().json;
const outline = $('解析大纲').first().json;
const ch1 = outline.chapter1 || {};
const ch2 = outline.chapter2 || {};
const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const chapters = [];
const pubA = $('校验发布A').first().json;
const pubB = $('校验发布B').first().json;
const draftA = $('解析草稿A').first().json;
const draftB = $('解析草稿B').first().json;
const qa = $('质量门A').first().json;
const qb = $('质量门B').first().json;
const aOk = pubA && pubA.published;
const bOk = pubB && pubB.published;
if (draftA && draftA.item_id) {
  chapters.push({ seq: meta.start_num, title: draftA.title, outline: ch1.outline || '', status: aOk ? 'published' : 'draft', words: Number(qa.chars || 0), fanqie_item_id: draftA.item_id, published_at: aOk ? now : '', error: aOk ? '' : JSON.stringify(pubA || {}).slice(0, 200) });
}
if (draftB && draftB.item_id) {
  chapters.push({ seq: meta.start_num + 1, title: draftB.title, outline: ch2.outline || '', status: bOk ? 'published' : 'draft', words: Number(qb.chars || 0), fanqie_item_id: draftB.item_id, published_at: bOk ? now : '', error: bOk ? '' : JSON.stringify(pubB || {}).slice(0, 200) });
}
const payload = {
  book_id: meta.book_id,
  book_name: meta.book_name,
  genre: outline.genre || '',
  premise: outline.premise || meta.premise,
  selling_point: '',
  platform: meta.platform || 'fanqie',
  tags: meta.tags || [],
  abstract: meta.abstract || '',
  protagonists: meta.protagonists || [],
  volume_goal: meta.volume_goal || '',
  outline: { premise: outline.premise, genre: outline.genre, title: outline.title, keywords: outline.keywords, chapter1: ch1, chapter2: ch2 },
  chapters: chapters
};
return [{ json: { payload_b64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];
